#include <cassert>
#include <filesystem>
int main(){const auto root=std::filesystem::current_path();std::filesystem::current_path(root/"TP_2023192003_CLIENT/client_sample");assert(gameFont().loadFromFile("neodgm.ttf") && clubhouseRenderer().load("assets/maps/clubhouse-sheet.png"));sf::RenderWindow window(sf::VideoMode(900,800),"Quest filter fixture",sf::Style::None);window.setVisible(false);g_window=&window;WindowDisplay::resize(window);travelState={};wardrobeState={};sc_packet_avatar_info info{};info.size=sizeof(info);info.type=S2C_P_AVATAR_INFO;info.id=7;info.region=1;info.x=12;info.y=16;info.hp=info.max_hp=10;ProcessPacket(reinterpret_cast<char*>(&info));
    auto key=[&](sf::Keyboard::Key k,bool release=false){sf::Event e{};e.type=release?sf::Event::KeyReleased:sf::Event::KeyPressed;e.key.code=k;return handleGameUiInput(e,window,{-1,-1});};auto press=[&](sf::Keyboard::Key k){key(k);key(k,true);};auto click=[&](sf::FloatRect r,bool outside=false){sf::Event e{};e.type=sf::Event::MouseButtonPressed;e.mouseButton.button=sf::Mouse::Left;handleGameUiInput(e,window,{r.left+5,r.top+5});e.type=sf::Event::MouseButtonReleased;handleGameUiInput(e,window,outside?sf::Vector2f{-1,-1}:sf::Vector2f{r.left+5,r.top+5});};
    for(int mode=0;mode<4;++mode){fieldJournalPanel().reset();questTracking.reset();townWalkQuest.reset();residentExperienceQuest.reset();pashminaExperienceQuest.reset();fieldDiscovery.reset();fieldDiscovery.start();fieldInvestigationPanel().reset();
        if(mode==1 || mode==3){fieldDiscovery.observe({world_regions::Id::SunnyPeak,32,32});fieldDiscovery.observe({world_regions::Id::SunnyPeak,90,96});townWalkQuest.accept(fieldDiscovery,true);townWalkQuest.report(fieldDiscovery,true);residentExperienceQuest.accept(true,true,true,fieldInvestigationPanel().state);pashminaExperienceQuest.accept(true,true,true,fieldInvestigationPanel().state);}
        if(mode==3){auto& a=fieldInvestigationPanel().state;for(const auto& l:field_landmarks::all){world_regions::Position p{world_regions::Id::SunnyPeak,l.x,l.y};a.open(p,true);a.begin(p,true,l.id*2000);a.tick(l.id*2000+900,p,true);a.close();}residentExperienceQuest.report(true,true,a);pashminaExperienceQuest.report(true,true,a);}
        press(sf::Keyboard::J);press(sf::Keyboard::Tab);if(mode){key(sf::Keyboard::F);key(sf::Keyboard::F);assert(fieldJournalPanel().activeOnly());key(sf::Keyboard::F,true);}if(mode==1){press(sf::Keyboard::Down);assert(fieldJournalPanel().selectedQuest()==2);click(ResidentQuestLogView::row(1));assert(fieldJournalPanel().selectedQuest()==2);press(sf::Keyboard::Enter);assert(questTracking.pinned()==3);}if(mode>=2){press(sf::Keyboard::Up);press(sf::Keyboard::Down);press(sf::Keyboard::Enter);assert(fieldJournalPanel().selectedQuest()==-1 && !questTracking.pinned());}
        const auto before=residentQuestSnapshot();for(auto size:{sf::Vector2u{900,800},sf::Vector2u{1280,720},sf::Vector2u{800,900}}){sf::RenderTexture out;assert(out.create(size.x,size.y));out.clear({32,24,24});auto f=display_layout::fit(size.x,size.y);sf::View v({0,0,900,800});v.setViewport({f.left/size.x,f.top/size.y,f.width/size.x,f.height/size.y});out.setView(v);clubhouseRenderer().draw(out,avatar.position.region,g_left_x,g_top_y);fieldJournalPanel().draw(out,gameFont(),avatar.position,fieldDiscovery,fieldInvestigationPanel().state,false,&guidedExperienceQuest(),residentQuestSnapshot());out.display();assert(out.getTexture().copyToImage().saveToFile((root/("build/tests/quest-filter-"+std::to_string(mode)+"-"+std::to_string(size.x)+"x"+std::to_string(size.y)+".png")).string()));}
        for(int i=0;i<3;++i)assert(before.rows[i].status==residentQuestSnapshot().rows[i].status);const auto filter=fieldJournalPanel().activeOnly();click(ResidentQuestLogView::filterButton,true);assert(fieldJournalPanel().activeOnly()==filter);click(ResidentQuestLogView::filterButton);assert(fieldJournalPanel().activeOnly()!=filter);press(sf::Keyboard::Escape);
    }press(sf::Keyboard::J);press(sf::Keyboard::Tab);press(sf::Keyboard::F);gameConnectionLost();assert(!fieldJournalPanel().activeOnly());fieldDiscovery.start();beginLoginConnection(0);assert(!fieldJournalPanel().activeOnly());std::puts("Quest filter production F/repeat/click outside/ID mapping/empty/read-only/reset +12renders PASS");}
